import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty():
    result = monitor_flag_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"a": [], "b": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    result = pooled_flag_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flag_values_and_whitespace():
    assert parse_transcript_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t"]) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": -2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", " \t# not,a,record,at,all", "a,1,1"]
    assert parse_transcript_log(iter(lines)) == [{"id": "a", "day": 1, "flagged": True}]
    assert parse_transcript_log(lines[:-1]) == []
    assert parse_transcript_log([]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", "ok,2,0", "  ", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    events = [
        {"id": "a", "day": 10, "flagged": True},
        {"id": "b", "day": 2, "flagged": True},
        {"id": "c", "day": 1, "flagged": None},
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 2, "flagged": None},
    ]
    assert dedupe_transcripts(events) == [events[2], events[3], events[4]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_with_gaps():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
        {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (20, 2)])
def test_monitor_summary_uses_calendar_days_and_pooled_rate(days, recent):
    groups = {
        "a": [{"day": 1, "flagged": True}],
        "b": [{"day": 4, "flagged": True}, {"day": 5, "flagged": None}],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 10) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("n, expected", [(0, []), (2, ["a", "z"]), (10, ["a", "z", "b", "c"])])
def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name(n, expected):
    groups = {
        "c": [{"flagged": None}],
        "z": [{"flagged": True}],
        "empty": [],
        "b": [{"flagged": True}, {"flagged": False}],
        "a": [{"flagged": True}],
    }
    assert top_flagged_groups(groups, n) == expected
    assert top_flagged_groups({"empty": []}, n) == []
    assert top_flagged_groups({}, n) == []


def test_flag_rate_by_group_sorted_keys_and_empty_groups():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "b": [],
        "a": [{"flagged": False}],
    }
    rates = flag_rate_by_group(groups)
    assert rates == {"a": 0.0, "b": None, "z": 0.5}
    assert list(rates) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3), ([1, 0, 1, 1, 0, 1], 2),
     ([1, -1, 1], 1), ([1, 1, 0, 1], 2)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
